package ru.truetv.bridge.android;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import ru.truetv.bridge.Wire;

/** Share target, not a second file manager. Discovery ends when the chooser leaves the foreground. */
public final class SendActivity extends Activity implements SendService.Listener {
 private final ArrayList<Uri> uris=new ArrayList<>();private final ArrayList<Discovery.Peer> peers=new ArrayList<>();private Discovery discovery;private TextView state;private ListView list;private Button cancel;private ProgressBar progress;private boolean sending;private String lastStatus;
 protected void onCreate(Bundle saved){super.onCreate(saved);requestWindowFeature(Window.FEATURE_NO_TITLE);BridgeUi.top(this);LinearLayout body=BridgeUi.box(this);body.addView(BridgeUi.label(this,"To TV",22));state=BridgeUi.label(this,"",16);body.addView(state);list=new ListView(this);list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,new ArrayList<String>()));list.setOnItemClickListener((p,v,pos,id)->send(peers.get(pos)));body.addView(list,new LinearLayout.LayoutParams(-1,BridgeUi.dp(this,170)));progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setVisibility(View.GONE);body.addView(progress,new LinearLayout.LayoutParams(-1,BridgeUi.dp(this,14)));cancel=BridgeUi.button(this,BridgeUi.w(this,"Отменить","Cancel"),()->{SendService s=SendService.active;if(s!=null&&!s.done)s.cancel();finish();});body.addView(cancel);setContentView(body);
  if(SendService.active!=null&&!SendService.active.done){sending=true;changed();return;}if(getIntent().getStringExtra("totv_result")!=null){state.setText(getIntent().getStringExtra("totv_result"));list.setVisibility(View.GONE);return;}Intent intent=getIntent();try{if(Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction())){ArrayList<Uri> incoming=intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(incoming!=null)uris.addAll(incoming);}else{Uri single=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(single!=null)uris.add(single);}if(uris.isEmpty()&&intent.getClipData()!=null)for(int i=0;i<intent.getClipData().getItemCount();i++){Uri u=intent.getClipData().getItemAt(i).getUri();if(u!=null)uris.add(u);}if(uris.isEmpty()||uris.size()>Wire.MAX_FILES)throw new IllegalArgumentException();for(Uri u:uris)if(u==null||!"content".equals(u.getScheme()))throw new IllegalArgumentException();}catch(RuntimeException e){state.setText(BridgeUi.w(this,"Выберите файлы в файловом менеджере → Отправить → To TV.","Select files in a file manager → Share → To TV."));list.setVisibility(View.GONE);return;}
  discovery=new Discovery(this,new Discovery.Listener(){public void peers(List<Discovery.Peer> found){peers.clear();peers.addAll(found);ArrayAdapter<String> a=(ArrayAdapter<String>)list.getAdapter();a.clear();for(Discovery.Peer p:peers)a.add(p.name+" · "+p.host.getHostAddress());a.notifyDataSetChanged();state.setText(BridgeUi.w(SendActivity.this,"Файлов: ","Files: ")+uris.size()+(found.isEmpty()?BridgeUi.w(SendActivity.this," · Поиск телевизоров…"," · Searching for TVs…"):BridgeUi.w(SendActivity.this," · Выберите телевизор"," · Choose a TV")));}public void error(String e){state.setText(BridgeUi.w(SendActivity.this,"Поиск недоступен: ","Discovery unavailable: ")+e);}});state.setText(BridgeUi.w(this,"Поиск телевизоров в локальной сети… Откройте приём файла на рабочем столе ТВ.","Finding TVs on the local network… Open Receive file on the TV desktop."));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},21);
 }
 private void send(Discovery.Peer peer){Intent i=new Intent(this,SendService.class).putParcelableArrayListExtra("uris",uris).putExtra("host",peer.host.getAddress()).putExtra("scope",peer.host instanceof java.net.Inet6Address?((java.net.Inet6Address)peer.host).getScopeId():0).putExtra("port",peer.port).putExtra("peer",peer.id).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);ClipData clip=ClipData.newRawUri("To TV",uris.get(0));for(int n=1;n<uris.size();n++)clip.addItem(new ClipData.Item(uris.get(n)));i.setClipData(clip);try{sending=true;if(discovery!=null)discovery.close();list.setVisibility(View.GONE);state.setText(BridgeUi.w(this,"Подключение…","Connecting…"));BridgeUi.start(this,i);}catch(RuntimeException e){sending=false;state.setText(BridgeUi.error(this,e));}}
 public void changed(){if(!sending)return;SendService s=SendService.active;if(s!=null){lastStatus=s.status;state.setText(s.status);list.setVisibility(View.GONE);progress.setVisibility(s.done?View.GONE:View.VISIBLE);progress.setIndeterminate(s.total<0);if(s.total>=0)progress.setProgress(s.total==0?1000:(int)Math.min(1000,1000d*s.bytes/s.total));cancel.setText(BridgeUi.w(this,s.done?"Закрыть":"Отменить",s.done?"Close":"Cancel"));}else if(sending){progress.setVisibility(View.GONE);cancel.setText(BridgeUi.w(this,"Закрыть","Close"));state.setText(lastStatus==null?BridgeUi.w(this,"Передача завершена. Результат — в уведомлении To TV.","Transfer ended. See the To TV notification."):lastStatus);}}
 protected void onResume(){super.onResume();SendService.observe(this);if(discovery!=null&&!sending)discovery.start();}protected void onPause(){SendService.observe(null);if(discovery!=null)discovery.close();super.onPause();}protected void onDestroy(){if(discovery!=null)discovery.close();super.onDestroy();}
}
